fn remove_duplicates(nums: &Vec<i32>) -> usize {
    let n = nums.len();
    if n == 0 {
        return 0;
    }
    // There's at least one element, so we start with one distinct value.
    let mut distinct_count = 1;
    // Scan through the sorted array and increment the count
    // whenever we see a new value different from the previous.
    for i in 1..n {
        if nums[i] != nums[i - 1] {
            distinct_count += 1;
        }
    }
    distinct_count
}

